import Foundation
import Vapor
import Crypto

// MARK: - Audit Logger with Fixed-Size Ring Buffer
final class AuditLogger {
    private var buffer: UnsafeMutableBufferPointer<UInt8>
    private var writeOffset: Int = 0
    private let capacity: Int
    private let headerSize: Int = 16
    private let lock = NSLock()

    init(capacity: Int = 4096) {
        self.capacity = capacity
        let raw = UnsafeMutablePointer<UInt8>.allocate(capacity: capacity)
        raw.initialize(repeating: 0, count: capacity)
        self.buffer = UnsafeMutableBufferPointer(start: raw, count: capacity)
    }

    deinit {
        buffer.baseAddress?.deallocate()
    }

    /// Computes the effective write length accounting for metadata envelope
    private func envelopeSize(for payload: Data) -> Int {
        // 4 bytes timestamp + 4 bytes payload length + payload + 4 bytes checksum + 4 bytes padding
        return headerSize + payload.count
    }

    /// Writes an audit entry into the ring buffer
    func writeEntry(action: String, user: String, metadata: [String: String]) {
        lock.lock()
        defer { lock.unlock() }

        let timestamp = UInt32(Date().timeIntervalSince1970)
        var entryData = Data()

        // Serialize metadata as key=value pairs separated by \x00
        var metaString = ""
        for (key, value) in metadata {
            metaString += "\(key)=\(value)\0"
        }

        let actionBytes = action.utf8
        let userBytes = user.utf8
        let metaBytes = metaString.utf8

        // Entry format: [action_len:2][action][user_len:2][user][meta_len:2][meta]
        let actionLen = UInt16(actionBytes.count)
        let userLen = UInt16(userBytes.count)
        let metaLen = UInt16(metaBytes.count)

        entryData.append(contentsOf: withUnsafeBytes(of: actionLen) { Array($0) })
        entryData.append(contentsOf: actionBytes)
        entryData.append(contentsOf: withUnsafeBytes(of: userLen) { Array($0) })
        entryData.append(contentsOf: userBytes)
        entryData.append(contentsOf: withUnsafeBytes(of: metaLen) { Array($0) })
        entryData.append(contentsOf: metaBytes)

        let totalSize = envelopeSize(for: entryData)

        // Bounds check: reject entries that exceed buffer capacity
        guard totalSize <= capacity else {
            return // Drop oversized entries silently
        }

        // Ring buffer wrap-around logic: check if we have space
        // If remaining space from writeOffset is sufficient, write linearly
        // Otherwise wrap to beginning
        let remainingLinear = capacity - writeOffset

        if remainingLinear >= totalSize {
            writeEnvelope(entryData: entryData, timestamp: timestamp, at: writeOffset, maxLen: remainingLinear)
            writeOffset = (writeOffset + totalSize) % capacity
        } else {
            // Wrap around - write at the beginning
            writeOffset = 0
            writeEnvelope(entryData: entryData, timestamp: timestamp, at: writeOffset, maxLen: capacity)
            writeOffset = totalSize % capacity
        }
    }

    /// Writes the envelope (header + payload + trailer) at the given offset
    private func writeEnvelope(entryData: Data, timestamp: UInt32, at offset: Int, maxLen: Int) {
        guard let base = buffer.baseAddress else { return }

        let totalNeeded = headerSize + entryData.count
        guard totalNeeded <= maxLen else { return }
        guard offset + totalNeeded <= capacity else { return }

        // Write timestamp (4 bytes)
        var ts = timestamp
        withUnsafeBytes(of: &ts) { tsBytes in
            (base + offset).initialize(from: tsBytes.bindMemory(to: UInt8.self).baseAddress!, count: 4)
        }

        // Write payload length (4 bytes)
        var payloadLen = UInt32(entryData.count)
        withUnsafeBytes(of: &payloadLen) { lenBytes in
            (base + offset + 4).initialize(from: lenBytes.bindMemory(to: UInt8.self).baseAddress!, count: 4)
        }

        // Write payload - bounded by capacity check above
        entryData.withUnsafeBytes { rawBuf in
            let src = rawBuf.bindMemory(to: UInt8.self)
            (base + offset + 8).initialize(from: src.baseAddress!, count: entryData.count)
        }

        // Write checksum (4 bytes) - simple XOR fold
        var checksum: UInt32 = 0
        for byte in entryData {
            checksum = checksum ^ UInt32(byte)
        }
        withUnsafeBytes(of: &checksum) { ckBytes in
            (base + offset + 8 + entryData.count).initialize(from: ckBytes.bindMemory(to: UInt8.self).baseAddress!, count: 4)
        }

        // Padding (4 bytes zeros)
        (base + offset + 12 + entryData.count).initialize(repeating: 0, count: 4)
    }

    /// Read recent entries for diagnostics
    func readBuffer() -> Data {
        lock.lock()
        defer { lock.unlock() }
        guard let base = buffer.baseAddress else { return Data() }
        return Data(bytes: base, count: capacity)
    }
}

// MARK: - Constant-time comparison helper
func constantTimeEquals(_ a: [UInt8], _ b: [UInt8]) -> Bool {
    guard a.count == b.count else { return false }
    var diff: UInt8 = 0
    for i in 0..<a.count {
        diff |= a[i] ^ b[i]
    }
    return diff == 0
}

// MARK: - Web Application
func configureRoutes(_ app: Application, logger: AuditLogger) {

    app.post("api", "login") { req -> Response in
        struct LoginRequest: Content {
            let username: String
            let password: String
            let clientInfo: [String: String]?
        }

        let loginReq = try req.content.decode(LoginRequest.self)

        // Limit metadata size to prevent abuse
        var metadata: [String: String] = [:]
        if let clientInfo = loginReq.clientInfo {
            // Only allow up to 5 metadata keys, each limited to 128 chars
            for (key, value) in clientInfo.prefix(5) {
                let safeKey = String(key.prefix(64))
                let safeValue = String(value.prefix(128))
                metadata[safeKey] = safeValue
            }
        }
        metadata["ip"] = req.remoteAddress?.description ?? "unknown"
        metadata["timestamp"] = ISO8601DateFormatter().string(from: Date())

        let safeUsername = String(loginReq.username.prefix(128))

        logger.writeEntry(
            action: "LOGIN_ATTEMPT",
            user: safeUsername,
            metadata: metadata
        )

        // Auth check via credential store
        if authenticateUser(loginReq.username, loginReq.password) {
            logger.writeEntry(action: "LOGIN_SUCCESS", user: safeUsername, metadata: metadata)
            return Response(status: .ok, body: .init(string: "{\"status\":\"ok\"}"))
        } else {
            logger.writeEntry(action: "LOGIN_FAILED", user: safeUsername, metadata: metadata)
            return Response(status: .unauthorized, body: .init(string: "{\"status\":\"denied\"}"))
        }
    }

    app.get("api", "audit") { req -> Response in
        // Require authorization: audit buffer contains sensitive data (usernames, IPs, metadata).
        guard let expectedToken = ProcessInfo.processInfo.environment["AUDIT_ACCESS_TOKEN"],
              !expectedToken.isEmpty else {
            // Fail closed if no token is configured.
            throw Abort(.forbidden)
        }
        guard let provided = req.headers.bearerAuthorization?.token,
              constantTimeEquals(Array(provided.utf8), Array(expectedToken.utf8)) else {
            throw Abort(.unauthorized)
        }

        let data = logger.readBuffer()
        return Response(status: .ok, body: .init(data: data))
    }
}

func authenticateUser(_ username: String, _ password: String) -> Bool {
    // Credentials sourced from environment / secure store, not hardcoded.
    guard let expectedUser = ProcessInfo.processInfo.environment["AUTH_USERNAME"],
          let expectedPassword = ProcessInfo.processInfo.environment["AUTH_PASSWORD"],
          !expectedUser.isEmpty, !expectedPassword.isEmpty else {
        // Fail closed if credentials are not configured.
        return false
    }
    let userMatch = constantTimeEquals(Array(username.utf8), Array(expectedUser.utf8))
    let passMatch = constantTimeEquals(Array(password.utf8), Array(expectedPassword.utf8))
    return userMatch && passMatch
}

// MARK: - Entry Point
func main() throws {
    let app = Application(.development)
    defer { app.shutdown() }

    let auditLogger = AuditLogger(capacity: 4096)
    configureRoutes(app, logger: auditLogger)

    try app.run()
}
